const fs = require\("fs"\);
const en = JSON.parse\(fs.readFileSync\("/Users/ivormyers/phototheology-palace-d387f2f4/src/i18n/locales/en.json", "utf8"\)\);
const sr = JSON.parse\(fs.readFileSync\("/tmp/sr_final.json", "utf8"\)\);

function findStillUntranslated\(ref, trans, path\) {
  path = path || "";
  var result = {};
  var keys = Object.keys\(ref\);
  for \(var i = 0; i < keys.length; i++\) {
    var key = keys[i];
    var fullPath = path ? path + "." + key : key;
    if \(typeof ref[key] === "string" && typeof trans[key] === "string"\) {
      if \(ref[key] === trans[key] && ref[key].length > 3\) {
        result[fullPath] = ref[key];
      }
    } else if \(typeof ref[key] === "object" && ref[key] != null && typeof trans[key] === "object" && trans[key] != null\) {
      var sub = findStillUntranslated\(ref[key], trans[key], fullPath\);
      Object.keys\(sub\).forEach\(function\(k\) { result[k] = sub[k]; }\);
    }
  }
  return result;
}

var remaining = findStillUntranslated\(en, sr\);
console.log\("Remaining:", Object.keys\(remaining\).length\);
Object.keys\(remaining\).forEach\(function\(k\) {
  console.log\(k + ": " + remaining[k]\);
}\);
