const fs = require\("fs"\);
const data = JSON.parse\(fs.readFileSync\("/tmp/hr_remaining.json", "utf8"\)\);
const keys = Object.keys\(data\);
const chunkSize = Math.ceil\(keys.length / 6\);
for \(var i = 0; i < 6; i++\) {
  var chunk = {};
  var start = i * chunkSize;
  var end = Math.min\(\(i + 1\) * chunkSize, keys.length\);
  for \(var j = start; j < end; j++\) {
    chunk[keys[j]] = data[keys[j]];
  }
  fs.writeFileSync\("/tmp/hr_batch_" + \(i+1\) + ".json", JSON.stringify\(chunk, null, 2\)\);
  console.log\("Batch " + \(i+1\) + ": " + Object.keys\(chunk\).length + " strings \(" + keys[start].split\("."\)[0] + " - " + keys[end-1].split\("."\)[0] + "\)"\);
}
SCRIPT)
